import {expedition,pressureReport,encodeSave,decodeSave} from './coastal-expedition.js';
import {mapLandmarks,landmarkImage,visibleLandmarks} from './coastal-landmarks.js';
import {geoStops as stops,regions} from './coastal-geography.js';
import {lineName,lineColour} from './coastal-lines.js';
export function installExpedition({root,side,controls,state,node,refresh,restore,engine}){
 const button=(label,action)=>{const b=node('button',label);b.type='button';b.onclick=action;return b;};
 function modal(title){const d=node('dialog',null,'coastal-shop coastal-expedition-shop');d.setAttribute('aria-label',title);let resume=false;d.append(button('Close '+title+' ×',()=>d.close()),node('h3',title));const content=node('div');d.append(content);root.append(d);d.addEventListener('click',event=>{if(event.target===d){const r=d.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)d.close();}});d.addEventListener('close',()=>{if(resume&&!state.complete&&!state.failed&&!root.querySelector('dialog[open]'))state.running=true;resume=false;refresh();});return {d,content,open(){resume=state.running;state.running=false;d.showModal();refresh();}};}
 const missions=node('section',null,'coastal-expedition-missions');missions.setAttribute('aria-label','Geography missions');side.append(missions);
 const passport=modal('Discovery collection');let filter='all';
 function renderCollection(){const e=expedition(state),known=visibleLandmarks(state);passport.content.replaceChildren(node('p',Object.keys(e.stamps).length+' / '+mapLandmarks.length+' landmark stamps collected. Deliver a passenger to a city and answer a question about its country to earn its stamp. Landmarks outside city stops are earned by visiting their country and answering a question.'));
  const filters=node('div',null,'coastal-collection-filters');for(const r of [{id:'all',name:'All countries'},...regions.filter(r=>r.round<=state.round)]){const b=button(r.name,()=>{filter=r.id;renderCollection();});b.setAttribute('aria-pressed',String(filter===r.id));filters.append(b);}passport.content.append(filters);
  const grid=node('div',null,'coastal-discovery-grid');for(const l of known.filter(l=>filter==='all'||l.region===filter)){const card=node('article',null,'coastal-discovery-stamp'),earned=e.stamps[l.id],picture=node('img');picture.src=landmarkImage(l);picture.alt=l.name;card.dataset.collected=String(Boolean(earned));card.append(picture,node('h4',l.name),node('small',regions.find(r=>r.id===l.region).name),node('p',earned?'✓ Collected · Round '+earned.round:'Visit '+(Number.isInteger(l.city)?stops[l.city].name:regions.find(r=>r.id===l.region).name)+' + answer a geography question'),node('p',l.description));const link=node('a','Read on Wikipedia ↗');link.href=l.source;link.target='_blank';link.rel='noopener';card.append(link);grid.append(card);}passport.content.append(grid);
 }
 side.append(button('✦ Discovery collection',()=>{renderCollection();passport.open();}));
 const overlay=button('◉ Route pressure',()=>{state.pressureOverlay=!state.pressureOverlay;refresh();});controls.append(overlay);
 const pressureKey=node('p','Route pressure: green = seats available · amber = add capacity · red = overloaded. Purple rings mark transfer stops. Unconnected passengers need a route to their destination shape.','coastal-pressure-key');side.append(pressureKey);
 const saves=modal('Save and resume'),status=node('p');status.setAttribute('aria-live','polite');let selected=null,lastSave=0,savedStage='';
 const stage=()=>[state.round,state.complete,state.failed,state.cardPhase,state.cardHistory.length].join('|');
 const key=i=>'coastal-journey-slot-'+i;
 function write(i,automatic=false){lastSave=performance.now();savedStage=stage();try{localStorage.setItem(key(i),encodeSave(state));selected=i;status.textContent=(automatic?'Autosaved':'Saved')+' to '+labels[i]+'.';return true;}catch{status.textContent='The browser could not save this journey. Free some storage and try again.';return false;}}
 const labels=['7A','7B','Year 8','Practice'];
 function renderSaves(){saves.content.replaceChildren(node('p','Four separate saves on this browser and device. Choose Save to replace a slot; Resume pauses the saved journey so you can inspect your network. The selected slot autosaves every 30 seconds during play.'),status);for(let i=0;i<labels.length;i++){const row=node('section',null,'coastal-save-slot');let raw=null,summary='Empty slot';try{raw=localStorage.getItem(key(i));if(raw){const saved=decodeSave(raw);summary=(saved.world==='kyrgyzstan'?'Kyrgyzstan':'United Kingdom')+' · '+(saved.language==='ru'?'Русский':saved.language==='ky'?'Кыргызча':'English')+' · Round '+saved.round+' · '+saved.credits+' 💷 · '+new Date(JSON.parse(raw).savedAt).toLocaleString();}}catch{summary='Unreadable save — you can replace it with a new save.';}
   row.append(node('h4',labels[i]+(selected===i?' · Autosave active':'')),node('p',summary),button('Save to '+labels[i],()=>{if(write(i))renderSaves();}));const load=button('Resume '+labels[i],()=>{try{const saved=decodeSave(localStorage.getItem(key(i)));selected=null;for(const d of root.querySelectorAll('dialog[open]'))d.close();setTimeout(()=>{restore(saved);selected=i;lastSave=performance.now();status.textContent='Resumed '+labels[i]+'.';refresh();},0);}catch(error){status.textContent=error.message;}});load.disabled=!raw;row.append(load);saves.content.append(row);}}
 side.append(button('▣ Save / resume',()=>{renderSaves();saves.open();}));
 let missionKey='';
 function update(){const e=expedition(state),stampCount=Object.keys(e.stamps).length,k=JSON.stringify([e.missions,stampCount]);if(k!==missionKey){missionKey=k;missions.replaceChildren(node('h4','GEOGRAPHY MISSIONS'));for(const m of e.missions){const card=node('article');card.dataset.complete=String(Boolean(m.claimed));card.append(node('strong',(m.claimed?'✓ ':'')+m.title),node('small',m.detail),node('span',m.progress+' / '+m.target+' · '+(m.claimed?'earned ':'+')+m.reward+' 💷'));missions.append(card);}missions.append(node('small','Passport · '+stampCount+' landmark stamps'));}overlay.setAttribute('aria-pressed',String(Boolean(state.pressureOverlay)));pressureKey.hidden=!state.pressureOverlay;if(selected!==null&&(stage()!==savedStage||state.running&&performance.now()-lastSave>=30000))write(selected,true);}
 function draw(ctx){if(!state.pressureOverlay)return;const reports=pressureReport(state,engine.lineStops,engine.passengerJourney,engine.vehicleStats),z=state.camera.zoom;ctx.save();for(const r of reports){const line=state.links[r.index],ids=engine.lineStops(line),a=stops[ids[Math.floor((ids.length-1)/2)]],b=stops[ids[Math.min(ids.length-1,Math.floor((ids.length-1)/2)+1)]],x=(a.x+b.x)/2,y=(a.y+b.y)/2,label=lineName(line.slot)+': '+r.waiting+' waiting / '+r.seats+' seats'+(r.unconnected?' · '+r.unconnected+' unconnected':'');ctx.font='bold '+12/z+'px system-ui';const w=ctx.measureText(label).width+16/z;ctx.fillStyle={high:'#f9c8c2',medium:'#ffe5a4',low:'#e0f2de'}[r.level];ctx.strokeStyle=lineColour(line.slot);ctx.lineWidth=2/z;ctx.beginPath();ctx.roundRect(x-w/2,y-15/z,w,25/z,6/z);ctx.fill();ctx.stroke();ctx.fillStyle='#164955';ctx.textAlign='center';ctx.fillText(label,x,y+2/z);for(const id of r.transfers){const p=stops[id];ctx.strokeStyle='#8764aa';ctx.lineWidth=3/z;ctx.beginPath();ctx.arc(p.x,p.y,29,0,Math.PI*2);ctx.stroke();}}
 for(const id of state.activeStops){const queue=state.passengers.filter(p=>p.at===id&&p.mode==='waiting'),p=stops[id];if(!queue.length)continue;ctx.font='bold '+13/z+'px system-ui';ctx.fillStyle=state.danger[id]>0?'#b73832':'#164955';ctx.fillText(queue.length+' waiting',p.x,p.y+58/z);}ctx.restore();}
 return {refresh:update,draw};
}
